'use client'

import { createViewTransition } from './view-transition-core'
import './transitions.css'

export type RiserOptions = {
  /** Which way the incoming page arrives from. */
  direction: 'up' | 'down' | 'left' | 'right'
  /** Seconds the swap takes. */
  duration: number
  /** Divides the duration. Above 1 is faster. */
  speed: number
  /** How far the outgoing page is pushed back, 0 to 1. Smaller is further. */
  depth: number
  /** How far the outgoing page travels as it recedes, in viewport units. */
  travel: number
  /** How dark the outgoing page goes as it falls behind, 0 to 1. */
  dim: number
}

const DEFAULTS: RiserOptions = {
  direction: 'up',
  duration: 0.7,
  speed: 1,
  depth: 0.8,
  travel: 30,
  dim: 0.4,
}

/**
 * The outgoing page drops back into depth while the incoming page is unmasked
 * over it. No JavaScript animates anything — both halves are a transform and a
 * clip-path, so the stylesheet drives it and the browser does the rest.
 */
export const RiserTransition = createViewTransition<RiserOptions>({
  name: 'riser',
  defaults: DEFAULTS,
  defs: null,
  duration: (o) => o.duration / o.speed,

  prepare: (o) => {
    const root = document.documentElement
    root.style.setProperty('--riser-depth', String(o.depth))
    root.style.setProperty('--riser-travel', `${o.travel}vh`)
    root.style.setProperty('--riser-travel-x', `${o.travel}vw`)
    root.style.setProperty('--riser-dim', String(o.dim))

    for (const d of ['up', 'down', 'left', 'right']) {
      root.classList.toggle(`riser-${d}`, d === o.direction)
    }
  },
})

'use client'

import { useEffect, useRef, type ReactNode } from 'react'
import { useRouter } from 'next/navigation'

export type ViewTransitionConfig<O> = {
  /**
   * Scopes this transition's stylesheet. The core puts `vt-<name>` on the
   * document element for the duration of the navigation, so two installed
   * transitions cannot both claim ::view-transition-old(root) — and neither
   * restyles a view transition it did not start.
   */
  name: string
  /** Values a consumer may override as props. */
  defaults: O
  /**
   * Rendered once and kept mounted. Masks and filters the stylesheet refers to
   * live here — they must sit above the page, because a page unmounts during
   * the navigation and would take its own defs with it.
   */
  defs: ReactNode | ((options: O) => ReactNode)
  /** Runs once per navigation, before the snapshot is taken. */
  prepare?: (options: O) => void
  /**
   * Drives one frame. progress runs 0 to 1. Omit it when the stylesheet does
   * the animating — the core still holds the snapshot open for the duration.
   */
  paint?: (progress: number, options: O) => void
  /** Seconds the transition should last. */
  duration: (options: O) => number
}

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/** Left alone: new tab, modified click, downloads, external, and same-page hashes. */
const isPlainInternalLink = (a: HTMLAnchorElement, e: MouseEvent) => {
  if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return false
  if (a.target && a.target !== '_self') return false
  if (a.hasAttribute('download')) return false
  const url = new URL(a.href, location.href)
  if (url.origin !== location.origin) return false
  if (url.pathname === location.pathname && url.hash) return false
  return true
}

/**
 * Turns a View Transitions config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <FilmBurnTransition>{children}</FilmBurnTransition>
 *
 * Unlike an overlay transition, this one has the outgoing page and the incoming
 * page on screen at the same time — the browser snapshots the old one — so the
 * effect can cut through one to the other rather than covering and uncovering.
 *
 * Browsers without the API navigate normally. Nothing breaks; there is simply
 * no animation.
 */
export function createViewTransition<O extends object>(config: ViewTransitionConfig<O>) {
  return function Transition({
    children,
    ...overrides
  }: { children: ReactNode } & Partial<O>) {
    const router = useRouter()
    const options = { ...config.defaults, ...(overrides as Partial<O>) } as O
    const latest = useRef(options)
    latest.current = options

    useEffect(() => {
      const onClick = (e: MouseEvent) => {
        const a = (e.target as Element | null)?.closest?.('a')
        if (!a || !isPlainInternalLink(a, e)) return

        const href = a.getAttribute('href')
        if (!href) return

        if (!document.startViewTransition || prefersReducedMotion()) return

        e.preventDefault()
        const o = latest.current
        const seconds = config.duration(o)

        try {
          config.prepare?.(o)
          config.paint?.(0, o)
        } catch (error) {
          console.error('[transition] prepare failed, navigating plainly', error)
          router.push(href)
          return
        }

        const root = document.documentElement
        root.classList.add(`vt-${config.name}`)
        root.style.setProperty('--vt-duration', `${seconds}s`)

        const transition = document.startViewTransition(() => {
          router.push(href)
        })

        const cleanup = () => root.classList.remove(`vt-${config.name}`)
        transition.finished.then(cleanup, cleanup)

        transition.ready
          .then(() => {
            // Holds the snapshot on screen. Without an animation of its own the
            // browser ends the transition on the next frame and the pseudo
            // elements vanish before anything has been drawn.
            document.documentElement.animate(
              { opacity: [1, 1] },
              { duration: seconds * 1000, pseudoElement: '::view-transition-old(root)' },
            )

            if (!config.paint) return

            const start = performance.now()
            const step = () => {
              const t = Math.min(1, (performance.now() - start) / (seconds * 1000))
              try {
                config.paint!(t, o)
              } catch (error) {
                console.error('[transition] paint failed', error)
                return
              }
              if (t < 1) requestAnimationFrame(step)
            }
            requestAnimationFrame(step)
          })
          .catch(() => {
            /* transition was skipped or superseded; the navigation still happened */
          })
      }

      document.addEventListener('click', onClick)
      return () => document.removeEventListener('click', onClick)
    }, [router])

    return (
      <>
        {children}
        {typeof config.defs === 'function' ? config.defs(options) : config.defs}
      </>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * inset:0 sizes to the layout viewport, which excludes the scrollbar — so the
 * overlay is centred on the area the reader actually sees. 100vw would include
 * the scrollbar and push the centre to the right of the content instead.
 */
.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
}

.transition-overlay svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* ---------- crayon ---------- */

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

/*
 * Every colour in the artwork reads from these, so overriding them anywhere
 * above the transition recolours the whole zip. Set your own values, or put one
 * of the preset classes below on any ancestor.
 */
:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-steel {
  --zip-metal-hi: #f8fbfe;
  --zip-metal: #c3ced8;
  --zip-metal-mid: #7c8894;
  --zip-metal-lo: #3f4750;
  --zip-metal-edge: #171b20;
  --zip-tape: #2b313a;
  --zip-tape-lo: #191d23;
}

.zip-brass {
  --zip-metal-hi: #fff8dd;
  --zip-metal: #eccb6f;
  --zip-metal-mid: #b8912f;
  --zip-metal-lo: #6b5115;
  --zip-metal-edge: #2b2107;
  --zip-tape: #3a3228;
  --zip-tape-lo: #231f18;
}

.zip-gunmetal {
  --zip-metal-hi: #c6ccd4;
  --zip-metal: #848b95;
  --zip-metal-mid: #4f555d;
  --zip-metal-lo: #2a2d33;
  --zip-metal-edge: #101216;
  --zip-tape: #1f2228;
  --zip-tape-lo: #121418;
}

.zip-copper {
  --zip-metal-hi: #ffe9d6;
  --zip-metal: #e2a179;
  --zip-metal-mid: #a95f37;
  --zip-metal-lo: #5d3018;
  --zip-metal-edge: #23110a;
  --zip-tape: #332822;
  --zip-tape-lo: #1d1714;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

/* ---------- film burn ---------- */

/*
 * The fire is its own colour, not the pages'. The outgoing page is masked away
 * inside the burn front, the incoming page is masked to show only inside a
 * slightly smaller front, and this ramp sits behind both — so what you see in
 * the gap between them is the fire itself.
 *
 * The ramp is anchored to the band rather than the origin. Anchored to the
 * origin, the visible annulus samples the cold end of the gradient once the
 * front is halfway out, and the fire goes dull.
 */
:root,
.burn-ember {
  --burn-core: #fff4dc;
  --burn-hot: #ffb32e;
  --burn-mid: #d94a12;
  --burn-edge: #6b1806;
}

/* Magnesium burns brilliant white and almost colourless — the point of it is
   that there is no hue, so this stays neutral all the way down. */
.burn-magnesium {
  --burn-core: #ffffff;
  --burn-hot: #f6f7f8;
  --burn-mid: #a9aeb4;
  --burn-edge: #34383d;
}

.burn-cold {
  --burn-core: #ddf5ff;
  --burn-hot: #33c9ff;
  --burn-mid: #0a5fd4;
  --burn-edge: #04123f;
}

.burn-toxic {
  --burn-core: #f4ffd9;
  --burn-hot: #c6ff3d;
  --burn-mid: #46b81a;
  --burn-edge: #0d3a0a;
}

.vt-film-burn ::view-transition-group(root) {
  animation: none;
  background:
    radial-gradient(
      circle at var(--burn-x, 50%) var(--burn-y, 50%),
      var(--burn-core) calc(var(--burn-cut, 0px) - var(--burn-band, 64px)),
      var(--burn-hot) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.68),
      var(--burn-mid) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.3),
      var(--burn-edge) var(--burn-cut, 0px),
      var(--burn-edge) 100%
    );
}

.vt-film-burn ::view-transition-image-pair(root) {
  isolation: auto;
}

/* The browser stacks the incoming snapshot above the outgoing one, so the
   outgoing page has to be lifted for its mask to read as a hole rather than as
   nothing at all. */
.vt-film-burn ::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 1;
  mask: url(#burn-mask-new);
  -webkit-mask: url(#burn-mask-new);
}

.vt-film-burn ::view-transition-old(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 2;
  mask: url(#burn-mask-old);
  -webkit-mask: url(#burn-mask-old);
}

/* ---------- riser ---------- */

/*
 * Nothing here is driven from JavaScript. The outgoing page is pushed back and
 * dimmed, the incoming page is unmasked over it, and the browser runs both off
 * the stylesheet — which is why this one needs no dependencies at all.
 */
.vt-riser::view-transition-group(root) {
  animation: none;
}

.vt-riser::view-transition-image-pair(root) {
  isolation: auto;
}

.vt-riser::view-transition-old(root) {
  animation: riser-recede var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 1;
  transform-origin: 50% 50%;
}

.vt-riser::view-transition-new(root) {
  animation: riser-arrive var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 2;
}

@keyframes riser-recede {
  to {
    opacity: var(--riser-dim, 0.4);
    transform: translate(var(--riser-out-x, 0), var(--riser-out-y, -30vh))
      scale(var(--riser-depth, 0.8));
  }
}

@keyframes riser-arrive {
  from {
    clip-path: var(--riser-from, inset(100% 0% 0% 0%));
  }
  to {
    clip-path: inset(0% 0% 0% 0%);
  }
}

/* The incoming page is unmasked from the edge it arrives at, and the outgoing
   page recedes the opposite way, so the two read as one movement. */
.riser-up {
  --riser-from: inset(100% 0% 0% 0%);
  --riser-out-y: calc(var(--riser-travel, 30vh) * -1);
  --riser-out-x: 0;
}

.riser-down {
  --riser-from: inset(0% 0% 100% 0%);
  --riser-out-y: var(--riser-travel, 30vh);
  --riser-out-x: 0;
}

.riser-left {
  --riser-from: inset(0% 0% 0% 100%);
  --riser-out-x: calc(var(--riser-travel-x, 30vw) * -1);
  --riser-out-y: 0;
}

.riser-right {
  --riser-from: inset(0% 100% 0% 0%);
  --riser-out-x: var(--riser-travel-x, 30vw);
  --riser-out-y: 0;
}

@media (prefers-reduced-motion: reduce) {
  .vt-riser::view-transition-old(root),
  .vt-riser::view-transition-new(root) {
    animation: none;
  }
}
